import{_ as s}from"./plugin-vue_export-helper-c27b6911.js";import{o as n,c as a,e}from"./app-4490560f.js";const t={},l=e(`<h1 id="tldr-简化的命令手册-community-cheatsheets" tabindex="-1"><a class="header-anchor" href="#tldr-简化的命令手册-community-cheatsheets" aria-hidden="true">#</a> tldr（简化的命令手册（community cheatsheets））</h1><blockquote><p>Homebrew 版本 1.0 ｜ 主页：见官方文档 ｜ 安装：<code>brew install tldr</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>tldr（Too Long; Didn&#39;t Read）是一个&quot;简化的命令行手册&quot;工具：它把 Linux/Unix 命令的官方 <code>man</code> 手册浓缩成一张张<strong>精简的速查表（cheatsheet）</strong>，只保留最常用、最实用的参数和示例，让你一眼就能上手某个命令，而不是在几千行的 man 手册里大海捞针。它解决的是&quot;知道有某个命令但记不住用法&quot;&quot;懒得翻 man 手册&quot;的痛点，典型应用场景是：快速复习 <code>tar</code>、<code>git</code>、<code>awk</code> 等常用命令的常见组合，或在新装的服务器上快速确认某个工具怎么用。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> tldr

<span class="token comment"># 升级</span>
brew upgrade tldr

<span class="token comment"># 卸载</span>
brew uninstall tldr

<span class="token comment"># 验证安装成功（查看版本）</span>
tldr <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装后 <code>tldr</code> 即进入 PATH，直接可全局调用。若之前用 <code>npm install -g tldr</code> 装过别的实现，建议先卸载旧版再 <code>brew install</code> 以免命令冲突。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>tldr 命令名</code></td><td>查看某个命令的简化手册</td><td><code>tldr tar</code></td></tr><tr><td><code>-p, --platform=平台</code></td><td>指定操作系统平台（linux / osx / sunos / windows / common）</td><td><code>tldr -p osx open</code></td></tr><tr><td><code>-r, --render=路径</code></td><td>渲染本地的手册文件（用于测试/自建）</td><td><code>tldr -r ./mypage.md tar</code></td></tr><tr><td><code>-u, --update</code></td><td>更新本地手册数据库</td><td><code>tldr --update</code></td></tr><tr><td><code>-c, --clear-cache</code></td><td>清空本地数据库缓存</td><td><code>tldr --clear-cache</code></td></tr><tr><td><code>-l, --list</code></td><td>列出本地数据库里的全部命令条目</td><td><code>tldr --list</code></td></tr><tr><td><code>-C, --color</code></td><td>强制彩色输出</td><td><code>tldr -C git</code></td></tr><tr><td><code>-V, --verbose</code></td><td>更新/清空缓存时显示详细过程</td><td><code>tldr -u -V</code></td></tr><tr><td><code>-L, --language=语言</code></td><td>指定输出语言（如 <code>zh</code>、<code>en</code>），优先级高于平台默认</td><td><code>tldr -L zh git</code></td></tr><tr><td><code>-e, --example=编号</code></td><td>只显示某个示例（多用于脚本解析）</td><td><code>tldr -e 2 tar</code></td></tr><tr><td><code>-a, --show-all</code></td><td>显示所有平台/语言的所有版本（<code>--update</code> 时全部拉取）</td><td><code>tldr -a git</code></td></tr><tr><td><code>--source=来源</code></td><td>指定数据源（官方仓库 / 镜像 / 自建服务器）</td><td><code>tldr --source 镜像 tldr</code></td></tr></tbody></table><blockquote><p>提示：<code>-V</code>（大写）是 verbose，<code>-v</code>（小写）才是版本号。</p></blockquote><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-查看-tar-命令的常用用法" tabindex="-1"><a class="header-anchor" href="#示例-1-查看-tar-命令的常用用法" aria-hidden="true">#</a> 示例 1：查看 <code>tar</code> 命令的常用用法</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：无需任何准备，tldr 首次使用时会自动下载数据库</span>
tldr <span class="token function">tar</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>输出形如：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>tar

  Archiving utility. Often combined with a compression method, such as gzip or bzip.
  More information: https://www.gnu.org/software/tar/.

  - Create an archive from files:
      tar cf target.tar file1 file2 file3

  - Create a gzipped archive:
      tar czf target.tar.gz file1 file2 file3

  - Extract a (compressed) archive into the current directory:
      tar xzf source.tar.gz
  ...
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-2-按平台查看-macos-与-linux-命令差异" tabindex="-1"><a class="header-anchor" href="#示例-2-按平台查看-macos-与-linux-命令差异" aria-hidden="true">#</a> 示例 2：按平台查看（macOS 与 Linux 命令差异）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># macOS 上查看 open 命令的速查（open 是 mac 专属）</span>
tldr <span class="token parameter variable">-p</span> osx <span class="token function">open</span>

<span class="token comment"># 查看 Linux 平台下的 ifconfig（不同平台参数不同）</span>
tldr <span class="token parameter variable">-p</span> linux <span class="token function">ifconfig</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-3-更新缓存并查看全部可用命令" tabindex="-1"><a class="header-anchor" href="#示例-3-更新缓存并查看全部可用命令" aria-hidden="true">#</a> 示例 3：更新缓存并查看全部可用命令</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 更新本地数据库到最新</span>
tldr <span class="token parameter variable">--update</span>

<span class="token comment"># 列出本地已有全部命令条目（方便发现新工具）</span>
tldr <span class="token parameter variable">--list</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-4-快速对比多个相似命令" tabindex="-1"><a class="header-anchor" href="#示例-4-快速对比多个相似命令" aria-hidden="true">#</a> 示例 4：快速对比多个相似命令</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 一口气查三个压缩/归档相关命令，快速对比用法</span>
tldr <span class="token function">tar</span> <span class="token operator">&amp;&amp;</span> tldr <span class="token function">zip</span> <span class="token operator">&amp;&amp;</span> tldr <span class="token function">gzip</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><p><strong>1. 用 shell 别名绑定常用命令速查</strong></p><p>在 <code>~/.zshrc</code> 或 <code>~/.bashrc</code> 里加：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">alias</span> <span class="token assign-left variable">tl</span><span class="token operator">=</span><span class="token string">&#39;tldr&#39;</span>        <span class="token comment"># 少敲几个字</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">man2</span><span class="token operator">=</span><span class="token string">&#39;tldr&#39;</span>      <span class="token comment"># 把 tldr 当&quot;精简 man&quot;用</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">t2</span><span class="token operator">=</span><span class="token string">&#39;tldr -L zh&#39;</span>  <span class="token comment"># 默认中文输出</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. 与 <code>which</code>/<code>command -v</code> 搭配快速查工具</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先确认命令确实存在，再查用法</span>
<span class="token builtin class-name">command</span> <span class="token parameter variable">-v</span> jq <span class="token operator">&amp;&amp;</span> tldr jq

<span class="token comment"># 查可执行文件的实际位置，避免查到别名/内置命令</span>
<span class="token function">which</span> <span class="token parameter variable">-a</span> <span class="token function">docker</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3. 与 fzf 联动，本地数据库交互式浏览</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 用 fzf 在本地命令列表里模糊选择再查看</span>
tldr <span class="token parameter variable">--list</span> <span class="token operator">|</span> fzf <span class="token operator">|</span> <span class="token function">xargs</span> -I<span class="token punctuation">{</span><span class="token punctuation">}</span> tldr <span class="token punctuation">{</span><span class="token punctuation">}</span>

<span class="token comment"># 带预览窗口（先看前几行再决定）</span>
tldr <span class="token parameter variable">--list</span> <span class="token operator">|</span> fzf <span class="token parameter variable">--preview</span> <span class="token string">&#39;tldr {} 2&gt;/dev/null&#39;</span> <span class="token operator">|</span> <span class="token function">xargs</span> -I<span class="token punctuation">{</span><span class="token punctuation">}</span> tldr <span class="token punctuation">{</span><span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>4. 数据库与缓存管理</strong></p><ul><li>首次运行 <code>tldr</code> 时自动下载数据库并缓存到本地；之后离线也能查。</li><li>若内容过旧或想强制刷新，运行 <code>tldr --update</code>。</li><li>清理缓存用 <code>tldr --clear-cache</code>，配合 <code>-V</code> 可看清理了哪些文件。</li><li>Homebrew 版的数据库默认放在 Homebrew 缓存目录下，一般无需手动干预。</li></ul><p><strong>5. 环境变量配置（TDLR 系列）</strong></p><p>tldr 客户端大量行为通过环境变量控制，常用如下：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 指定数据库目录（默认在缓存目录，可自定义到 ~/.config/tldr）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">TLDR_CACHE_DIR</span><span class="token operator">=</span><span class="token string">&quot;<span class="token environment constant">$HOME</span>/.config/tldr&quot;</span>

<span class="token comment"># 指定 tldr 客户端实现（可选 homebrew、node、python 等）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">TLDR_PLATFORM</span><span class="token operator">=</span>linux      <span class="token comment"># 强制平台</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">TLDR_LANGUAGE</span><span class="token operator">=</span>zh         <span class="token comment"># 强制语言，效果等同 -L zh</span>

<span class="token comment"># 指定自定义数据源（官方 / 镜像 / 自建 tldr 服务）</span>
<span class="token comment"># 不同客户端变量名略有差异，常见有 TLDR_SOURCE / TLDR_MIRROR</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">TLDR_SOURCE</span><span class="token operator">=</span>https://tldr.mirror.example.com

<span class="token comment"># 关闭颜色或强制颜色</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">NO_COLOR</span><span class="token operator">=</span><span class="token number">1</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>写进 <code>~/.zshrc</code> 后，所有 tldr 调用自动生效，无需每次加参数。</p><p><strong>6. 常用配置项速查（<code>tldr --help</code> 可全量查看）</strong></p><table><thead><tr><th>配置项</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>--language</code></td><td>输出语言</td><td><code>tldr --language zh git</code></td></tr><tr><td><code>--platform</code></td><td>输出平台</td><td><code>tldr --platform osx open</code></td></tr><tr><td><code>--source</code></td><td>数据源</td><td><code>tldr --source 镜像 tar</code></td></tr><tr><td><code>--example</code></td><td>只显示指定序号示例</td><td><code>tldr --example 3 tar</code></td></tr><tr><td><code>--show-all</code></td><td>显示全部平台/语言版本</td><td><code>tldr --show-all git</code></td></tr><tr><td><code>--color</code></td><td>强制颜色</td><td><code>tldr --color tar</code></td></tr><tr><td><code>--no-color</code></td><td>关闭颜色（管道脚本场景）</td><td><code>tldr --no-color tar</code></td></tr></tbody></table><p><strong>7. 本地渲染与自建条目测试</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 渲染一个尚未进库的手写 md 文件，验证格式再提交</span>
tldr <span class="token parameter variable">-r</span> ./mypage.md <span class="token function">tar</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>8. 个性化：自定义 logo / 配色</strong></p><p>tldr 客户端本身不渲染 logo，但你可结合 <code>bat</code> 给输出套一层主题色，或用一个 wrapper 函数统一风格：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 给 tldr 套 bat 主题（先 brew install bat）</span>
<span class="token function-name function">tldr-bat</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> tldr <span class="token string">&quot;<span class="token variable">$@</span>&quot;</span> <span class="token operator">|</span> bat <span class="token parameter variable">--language</span><span class="token operator">=</span>man <span class="token parameter variable">--style</span><span class="token operator">=</span>grid<span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>9. 深入：平台命令差异的正确处理</strong></p><p>tldr 的速查表按平台细分（<code>linux</code> / <code>osx</code> / <code>sunos</code> / <code>windows</code> / <code>common</code>），<strong>同名命令在不同平台参数往往不同</strong>，这是新手最容易踩的坑：</p><p><strong>① 先看当前平台默认走哪个</strong></p><p>macOS 上跑 <code>tldr sed</code>，默认查的是 <code>osx</code> 平台页；Linux 上跑则是 <code>linux</code> 页。两个页面的 <code>sed -i</code> 用法<strong>截然不同</strong>（macOS BSD 版要 <code>-i.bak</code>，GNU 版直接 <code>-i</code>）。</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># macOS 上显式指定 Linux 页，看 GNU 用法</span>
tldr <span class="token parameter variable">-p</span> linux <span class="token function">sed</span>

<span class="token comment"># 显示该命令在所有平台的所有页面，逐一对比差异</span>
tldr <span class="token parameter variable">-a</span> <span class="token function">sed</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>② 用 <code>-a</code> 看&quot;同一个命令的所有平台版本&quot;</strong></p><p><code>tldr -a 命令名</code> 会把 <code>linux</code>、<code>osx</code>、<code>windows</code> 的页面<strong>全部展开</strong>，是对比&quot;跨平台命令差异&quot;的最快方式。写脚本要跨平台时，先 <code>-a</code> 对比参数再写，能避免大量返工。</p><p><strong>③ 给&quot;常用但有平台差异&quot;的命令建别名</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 在 mac 上做 GNU 风格替换，先装 gsed 再定义</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">sed</span><span class="token operator">=</span><span class="token string">&#39;gsed&#39;</span>            <span class="token comment"># GNU sed（需 brew install gnu-sed）</span>
<span class="token builtin class-name">alias</span> tldr-sed<span class="token operator">=</span><span class="token string">&#39;tldr -p linux sed&#39;</span>   <span class="token comment"># 直接查 GNU 页</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>④ 平台页缺失时的兜底</strong></p><p>某命令只有 <code>linux</code> 页没有 <code>osx</code> 页时，mac 上直接 <code>tldr cmd</code> 会提示找不到。此时：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 显式指定有页的平台（如 linux）</span>
tldr <span class="token parameter variable">-p</span> linux <span class="token function">apt</span>
<span class="token comment"># 或强制只查 common 公共页</span>
tldr <span class="token parameter variable">-p</span> common <span class="token function">env</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>10. 深入：自建 / 私有 tldr 页面</strong></p><p><strong>① 原理</strong>：tldr 页面本质是带约定格式的 Markdown 文件，放在本地目录或自建服务器，客户端用 <code>--source</code> 指向即可。这让你能维护<strong>团队内部私有命令</strong>的速查表，甚至补全社区没有的冷门命令。</p><p><strong>② 约定格式（必须是这个结构，否则渲染报错）</strong>：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code><span class="token title important"><span class="token punctuation">#</span> cmdname</span>

<span class="token blockquote punctuation">&gt;</span> 一行简介。支持 <span class="token url">[<span class="token content">链接</span>](<span class="token url">https://example.com</span>)</span>。

<span class="token list punctuation">-</span> 第一个示例：描述

<span class="token code-snippet code keyword">\`cmdname --flag arg1\`</span>

<span class="token list punctuation">-</span> 第二个示例：描述

<span class="token code-snippet code keyword">\`cmdname subcommand arg2\`</span>

<span class="token list punctuation">-</span> 更多信息: &lt;https://example.com&gt;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>写完后用 <code>-r</code> 本地渲染验证：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>tldr <span class="token parameter variable">-r</span> ./mydoc.md          <span class="token comment"># 渲染本地页面，检查格式是否合法</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>③ 本地私有页目录 + 自动追加到查询链</strong></p><p>不同客户端支持程度不同，常见的做法是把私有页放进一个目录，再封装成函数，让 <code>tldr</code> 查不到公共页时回退到私有页：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># ~/.zshrc —— 团队私有速查封装</span>
<span class="token function-name function">mytldr</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token builtin class-name">local</span> <span class="token assign-left variable">page</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">$1</span>&quot;</span>
  <span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token parameter variable">-f</span> <span class="token string">&quot;<span class="token environment constant">$HOME</span>/.tldr-local/<span class="token variable">$1</span>.md&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span>
    tldr <span class="token parameter variable">-r</span> <span class="token string">&quot;<span class="token environment constant">$HOME</span>/.tldr-local/<span class="token variable">$1</span>.md&quot;</span>   <span class="token comment"># 命中私有页则渲染本地</span>
  <span class="token keyword">else</span>
    tldr <span class="token string">&quot;<span class="token variable">$@</span>&quot;</span>                            <span class="token comment"># 否则走公共库</span>
  <span class="token keyword">fi</span>
<span class="token punctuation">}</span>
<span class="token comment"># 用法：mytldr deploy  —— 先查私有页，没有再走公共库</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>④ 自建 HTTP 源</strong></p><p>若公司内网有统一速查服务器，可用 <code>--source</code> 指向：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 指向自建 tldr 服务（需按 tldr 的 zip/md 结构提供服务）</span>
tldr <span class="token parameter variable">--source</span> https://tldr.internal.example.com <span class="token parameter variable">--update</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>⑤ 用 <code>-e</code> 只取某条示例，供脚本复用</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 只显示第 2 条示例（脚本提取命令体）</span>
tldr <span class="token parameter variable">-e</span> <span class="token number">2</span> <span class="token function">tar</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>11. 深入：脚本搭配（把 tldr 当数据源）</strong></p><p>tldr 虽为人类阅读设计，但配合 <code>-e</code>/<code>-N</code>/<code>--no-color</code> 可稳定输出供脚本解析：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 关闭颜色 + 关闭行号 + 只取示例，输出最干净</span>
tldr --no-color <span class="token parameter variable">-N</span> <span class="token function">tar</span>

<span class="token comment"># 取第 1 条示例的命令体（缩进行），供脚本复用</span>
tldr --no-color <span class="token function">tar</span> <span class="token operator">|</span> <span class="token function">sed</span> <span class="token parameter variable">-n</span> <span class="token string">&#39;s/^  \\(.*\\)$/\\1/p&#39;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-v</span> <span class="token string">&#39;^$&#39;</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-1</span>

<span class="token comment"># 判断某命令是否有速查页（脚本门禁用）</span>
<span class="token keyword">if</span> tldr <span class="token string">&quot;<span class="token variable">$cmd</span>&quot;</span> <span class="token operator">&gt;</span>/dev/null <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span><span class="token punctuation">;</span> <span class="token keyword">then</span> <span class="token builtin class-name">echo</span> <span class="token string">&quot;has page&quot;</span><span class="token punctuation">;</span> <span class="token keyword">else</span> <span class="token builtin class-name">echo</span> <span class="token string">&quot;missing&quot;</span><span class="token punctuation">;</span> <span class="token keyword">fi</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>12. 与其它工具搭配速查</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 查 man 太冗长时，先 tldr 快速上手</span>
<span class="token comment"># 想深入再 man 看权威细节 —— 组合成&quot;速查漏斗&quot;</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">quick</span><span class="token operator">=</span><span class="token string">&#39;tldr $1 &amp;&amp; echo &quot;—— 想深入请 man &#39;</span><span class="token variable">$1</span><span class="token string">&#39;&quot;&#39;</span>

<span class="token comment"># 与 fzf 联动：交互式翻本地命令库</span>
tldr <span class="token parameter variable">--list</span> <span class="token operator">|</span> fzf <span class="token parameter variable">--preview</span> <span class="token string">&#39;tldr {} 2&gt;/dev/null&#39;</span> <span class="token operator">|</span> <span class="token function">xargs</span> tldr

<span class="token comment"># 与脚本批处理：批量抽查一批命令是否有速查</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">cmd</span> <span class="token keyword">in</span> <span class="token function">git</span> <span class="token function">awk</span> <span class="token function">sed</span> jq <span class="token function">curl</span><span class="token punctuation">;</span> <span class="token keyword">do</span> tldr <span class="token string">&quot;<span class="token variable">$cmd</span>&quot;</span> <span class="token operator">&gt;</span>/dev/null <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span> <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">echo</span> <span class="token string">&quot;OK <span class="token variable">$cmd</span>&quot;</span> <span class="token operator">||</span> <span class="token builtin class-name">echo</span> <span class="token string">&quot;MISS <span class="token variable">$cmd</span>&quot;</span><span class="token punctuation">;</span> <span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><p><strong>1. 首次使用需要联网</strong></p><p>第一次运行 <code>tldr</code> 会从网络拉取数据库，如果没网或代理配置不对，会报错或卡住。解决办法：检查网络/代理后重试，或先 <code>tldr --update</code> 手动触发下载。</p><p><strong>2. <code>-v</code> 与 <code>-V</code> 别搞混</strong></p><ul><li><code>tldr -v</code>：打印版本号。</li><li><code>tldr -V</code>（大写）：配合 <code>-u</code>/<code>-c</code> 显示详细输出。<br> 新手常把大写当版本号用而报错。</li></ul><p><strong>3. 命令名大小写与平台差异</strong></p><p>tldr 的速查表按平台区分，<code>osx</code>（macOS）与 <code>linux</code> 的同名命令参数可能不同。在 macOS 上查 Linux 专用命令（如 <code>apt</code>）时，记得加 <code>-p linux</code> 否则可能提示找不到。</p><p><strong>4. 找不到某个命令</strong></p><p>如果 <code>tldr foo</code> 提示找不到，可能原因：</p><ul><li>该命令确实没有对应的速查表（tldr 覆盖的是社区常见命令）。</li><li>数据库太旧，先 <code>tldr --update</code> 再试。</li><li>也可以用 <code>tldr --list | grep foo</code> 确认是否收录。</li><li>命令是&quot;别名/内置/函数&quot;而非独立二进制：<code>type foo</code> 看来源，<code>tldr</code> 只收录有速查页的独立命令。</li></ul><p><strong>5. 它只是速查表，不是完整手册</strong></p><p>tldr 只提供最常用参数，不覆盖 man 的全部细节。遇到边界情况、高级配置或版本差异时，仍应以 <code>man 命令名</code> 或官方文档为准——把 tldr 当作&quot;快速上手入口&quot;，man 当作&quot;权威参考&quot;。</p><p><strong>6. 数据库是社区维护的，可能有瑕疵</strong></p><p>tldr 的速查表由 tldr-pages 社区众包维护，个别条目可能过时或不完整。命令行为与预期不符时，多结合 <code>man</code> 和 <code>--version</code> 交叉核对。</p><p><strong>7. 中文输出不全或乱码</strong></p><ul><li>若 <code>-L zh</code> 无中文，可能该命令尚未有中文翻译页，退回英文属正常现象。</li><li>终端编码问题：确认 <code>$LANG</code> 为 <code>UTF-8</code>（如 <code>export LANG=en_US.UTF-8</code>）。</li></ul><p><strong>8. 代理 / 镜像环境拉取失败</strong></p><p>公司内网或受限网络下，<code>--update</code> 常超时。解决：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 走代理</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">HTTPS_PROXY</span><span class="token operator">=</span>http://127.0.0.1:7890
<span class="token comment"># 或切换数据源/镜像</span>
tldr <span class="token parameter variable">--source</span> 镜像 <span class="token parameter variable">--update</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>9. 自建页渲染报错的常见原因</strong></p><table><thead><tr><th>现象</th><th>原因</th><th>解决办法</th></tr></thead><tbody><tr><td><code>-r</code> 渲染后格式错乱</td><td>Markdown 标题层级或代码块符号不对</td><td>严格按&quot;页面约定格式&quot;（<code># 名</code>、<code>&gt; 简介</code>、<code>- 描述</code> + 代码块）</td></tr><tr><td>中文注释乱码</td><td>文件非 UTF-8</td><td>确认用 UTF-8 无 BOM 保存</td></tr><tr><td>首行不是 <code># 命令名</code></td><td>客户端按首行识别命令名</td><td>保证第一行是 <code># 命令名</code></td></tr><tr><td>代码块未用反引号包裹</td><td>命令体需在 <code>\`</code> 反引号内</td><td>每条示例的命令行用反引号包住</td></tr></tbody></table><p><strong>10. 性能 / 安全注意</strong></p><ul><li>日常查询走本地缓存、离线可查，几乎无 IO 开销；不必频繁 <code>--update</code>。</li><li>不要盲目信任脚本里 <code>tldr</code> 输出的示例并直接执行——个别示例含占位符或依赖环境，建议先 <code>man</code> 确认再跑。</li><li>若提示需你手动下载一个&quot;压缩包/脚本&quot;，务必核验来源，避免供应链风险。</li><li><strong>自建源的安全</strong>：用 <code>--source</code> 指向自建服务器时，确认该源受控、可信；<code>--update</code> 会从该源拉取内容，若被篡改可能诱导执行恶意命令。</li></ul><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><p><strong>1. 与 grep / 脚本配合做命令速查批处理</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 一批命令逐个出速查</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">cmd</span> <span class="token keyword">in</span> <span class="token function">tar</span> <span class="token function">gzip</span> <span class="token function">zip</span> <span class="token function">curl</span><span class="token punctuation">;</span> <span class="token keyword">do</span> tldr <span class="token variable">$cmd</span><span class="token punctuation">;</span> <span class="token keyword">done</span>

<span class="token comment"># 只取命令名，便于集成进文档</span>
tldr <span class="token parameter variable">--list</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-E</span> <span class="token string">&#39;^(git|awk|sed)&#39;</span>

<span class="token comment"># 提取某条示例的命令体（第二行缩进内容），供脚本复用</span>
tldr <span class="token function">tar</span> <span class="token operator">|</span> <span class="token function">sed</span> <span class="token parameter variable">-n</span> <span class="token string">&#39;s/^  \\(.*\\)$/\\1/p&#39;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-v</span> <span class="token string">&#39;^$&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. 与 fd 搭配做&quot;新工具速查&quot;巡览</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 列出 /usr/local/bin 下常用工具，挨个出速查（可控输出）</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">bin</span> <span class="token keyword">in</span> <span class="token variable"><span class="token variable">$(</span>fd <span class="token parameter variable">-t</span> x <span class="token parameter variable">-d</span> <span class="token number">1</span> <span class="token parameter variable">-x</span> <span class="token function">basename</span> <span class="token punctuation">{</span><span class="token punctuation">}</span> /usr/local/bin <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-30</span><span class="token variable">)</span></span><span class="token punctuation">;</span> <span class="token keyword">do</span>
  tldr <span class="token string">&quot;<span class="token variable">$bin</span>&quot;</span> <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null
<span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3. 与 sed / awk 联用做格式化</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 把输出转成 Markdown 用 （粗配，需结合 sed 清洗）</span>
tldr <span class="token parameter variable">--list</span> <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print &quot;## &quot; $0}&#39;</span> <span class="token operator">|</span> <span class="token function">head</span>

<span class="token comment"># 去色、去行号后落盘，供离线文档</span>
tldr --no-color <span class="token function">tar</span> <span class="token operator">&gt;</span> tar-cheatsheet.txt
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>4. Makefile 自动化：新装环境自动灌入速查库</strong></p><p>在项目根目录放 <code>Makefile</code>：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> tldr-setup tldr-refresh tldr-team

<span class="token target symbol">tldr-setup</span><span class="token punctuation">:</span>
	command -v tldr &gt;/dev/null <span class="token operator">|</span><span class="token operator">|</span> brew install tldr
	tldr --update

<span class="token target symbol">tldr-refresh</span><span class="token punctuation">:</span>
	tldr --update &amp;&amp; tldr --list <span class="token operator">|</span> wc -l

<span class="token comment"># 导出团队常用命令的速查为离线文档</span>
<span class="token target symbol">tldr-team</span><span class="token punctuation">:</span>
	mkdir -p docs/cheats
	for c in git docker kubectl make<span class="token punctuation">;</span> do tldr --no-color <span class="token string">&quot;$$c&quot;</span> &gt; docs/cheats/<span class="token variable">$$c.md;</span> done
	<span class="token operator">@</span>echo <span class="token string">&quot;已导出到 docs/cheats/&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 使用</span>
<span class="token function">make</span> tldr-setup    <span class="token comment"># 首次：装 tldr 并拉库</span>
<span class="token function">make</span> tldr-refresh  <span class="token comment"># 后续：刷新并统计条目数</span>
<span class="token function">make</span> tldr-team     <span class="token comment"># 导出团队常用速查为文档</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>5. CI 集成：在流水线里校验命令速查</strong></p><p>GitHub Actions 示例 <code>.github/workflows/tldr-check.yml</code>：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> tldr<span class="token punctuation">-</span>check
<span class="token key atrule">on</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>push<span class="token punctuation">]</span>
<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">check</span><span class="token punctuation">:</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> 安装并更新 tldr
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          sudo apt-get update &amp;&amp; sudo apt-get install -y tldr
          tldr --update</span>
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> 校验关键命令速查存在
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          for c in git tar awk jq; do
            tldr &quot;$c&quot; &gt;/dev/null &amp;&amp; echo &quot;OK: $c&quot; || { echo &quot;MISSING: $c&quot;; exit 1; }
          done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>6. 批量提取+文档生成</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 把常用命令速查批量导出为 Markdown 文档，方便团队分享</span>
<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> cheats
<span class="token keyword">for</span> <span class="token for-or-select variable">cmd</span> <span class="token keyword">in</span> <span class="token function">git</span> <span class="token function">curl</span> <span class="token function">docker</span><span class="token punctuation">;</span> <span class="token keyword">do</span>
  tldr --no-color <span class="token string">&quot;<span class="token variable">$cmd</span>&quot;</span> <span class="token operator">&gt;</span> <span class="token string">&quot;cheats/<span class="token variable">$cmd</span>.md&quot;</span>
<span class="token keyword">done</span>
<span class="token comment"># 生成索引</span>
<span class="token builtin class-name">printf</span> <span class="token string">&#39;# 常用速查\\n\\n&#39;</span> <span class="token operator">&gt;</span> cheats/README.md
<span class="token function">ls</span> cheats/*.md <span class="token operator">|</span> <span class="token function">sed</span> <span class="token string">&#39;s#cheats/##;s#\\.md$##&#39;</span> <span class="token operator">|</span> <span class="token function">sed</span> <span class="token string">&#39;s#^#- []#;s#$#](cheats/&amp;.md)#&#39;</span> <span class="token operator">&gt;&gt;</span> cheats/README.md
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>7. 自建团队速查库 + 部署为离线/内网页</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1) 用脚本把常用命令批量导出为本地 Markdown 页</span>
<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> ~/.tldr-local
<span class="token keyword">for</span> <span class="token for-or-select variable">c</span> <span class="token keyword">in</span> deploy rollback healthcheck<span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token comment"># 为团队私有命令编写约定格式页面，见第五节&quot;自建页面&quot;</span>
  <span class="token function">cat</span> <span class="token operator">&gt;</span> ~/.tldr-local/<span class="token variable">$c</span>.md <span class="token operator">&lt;&lt;</span> <span class="token string">EOF
# <span class="token variable">$c</span>

&gt; 团队内部部署命令速查。

- 部署到 staging：\\<span class="token variable"><span class="token variable">\`</span>deploy <span class="token parameter variable">--env</span> staging<span class="token punctuation">\\</span><span class="token variable">\`</span></span>

- 回滚上一个版本：\\<span class="token variable"><span class="token variable">\`</span>deploy --rollback<span class="token punctuation">\\</span><span class="token variable">\`</span></span>
EOF</span>
<span class="token keyword">done</span>

<span class="token comment"># 2) 封装 mytldr 函数（见第五节），让私有页优先</span>
<span class="token comment"># 3) 若团队大，可把私有页推送到自建 HTTP 服务，用 --source 统一分发</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>8. 生产级实践建议</strong></p><ul><li>把 <code>tldr</code> 与 <code>man</code>、<code>info</code>、<code>help</code> 组合成&quot;速查漏斗&quot;：<code>tldr</code>（快）→ <code>man</code>（全）→ <code>info</code>（权威）。</li><li>在团队 onboarding 脚本里预装 tldr 并 <code>--update</code>，新成员开箱即用。</li><li>定期（如每周 cron）<code>tldr --update</code>，保持速查不过期：</li></ul><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># crontab：每周一 3 点刷新</span>
<span class="token number">0</span> <span class="token number">3</span> * * <span class="token number">1</span> tldr <span class="token parameter variable">--update</span> <span class="token operator">&gt;&gt;</span> ~/.local/log/tldr.log <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>自建内网 tldr 服务时，用 <code>--source</code> 指向内部地址，避免公网访问受限并统一版本。</li><li>把&quot;平台差异提醒&quot;写进团队 wiki：mac/Linux 下 <code>sed</code>、<code>find</code>、<code>du</code>、<code>tar</code> 等命令参数差异最大，写脚本前先 <code>tldr -a 命令</code> 对比，能省大量调试时间。</li><li>用 <code>TLDR_LANGUAGE=zh</code> + <code>-L en</code> 临时切换，兼顾中文速查与英文原版准确性，两头不误。</li><li>自建页面纳入 git 版本管理，团队私有速查随代码库演进，随人随环境可迁移。</li></ul>`,118),o=[l];function d(c,i){return n(),a("div",null,o)}const u=s(t,[["render",d],["__file","tldr.html.vue"]]);export{u as default};
